// mep's Julia formatter, driven directly.
//
// `mep-julia-format-test` runs the checks below;
// `mep-julia-format-test --format [-w N] [--indent N] FILE...` prints each file
// formatted ('-' reads stdin), for tools/format_compare.py. Generated by
// tools/new_language.py.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

#include "julia_format.h"

namespace {
int g_checks = 0;

void Check(bool ok, const char *expr, int line) {
    g_checks++;
    if (ok) return;
    std::fprintf(stderr, "CHECK FAILED: %s at %s:%d\n", expr, __FILE__, line);
    std::abort();
}
#define CHECK(c) Check((c), #c, __LINE__)

int FormatFiles(int argc, char **argv) {
    juliafmt::Options opts;
    int status = 0;
    for (int k = 2; k < argc; k++) {
        const std::string arg = argv[k];
        if ((arg == "-w" || arg == "--width") && k + 1 < argc) {
            opts.width = std::atoi(argv[++k]);
            continue;
        }
        if (arg == "--indent" && k + 1 < argc) {
            opts.indent = std::atoi(argv[++k]);
            continue;
        }
        std::stringstream ss;
        if (arg == "-") {
            ss << std::cin.rdbuf();
        } else {
            std::ifstream in(arg, std::ios::binary);
            ss << in.rdbuf();
        }
        const juliafmt::Result r = juliafmt::Format(ss.str(), opts);
        if (!r.ok) {
            std::fprintf(stderr, "%s:%d: %s\n", arg.c_str(), r.error_line, r.error.c_str());
            status = 1;
            continue;
        }
        std::fwrite(r.text.data(), 1, r.text.size(), stdout);
    }
    return status;
}

// Inputs and Runic.jl 1.5.0's output for them (`runic FILE`, filemode).
struct Case {
    const char *src;
    const char *want;
};
const Case kCases[] = {
    {R"jl(function f(x,y)
  z=x+y
  if z>1
	return z
  end
  z
end
)jl",
     R"jl(function f(x, y)
    z = x + y
    if z > 1
        return z
    end
    return z
end
)jl"},
    {R"jl(for i=1:10, j∈1:2 println(i) end
x = [1,2 ,3]
y = (a=1,b=2)
)jl",
     R"jl(for i in 1:10, j in 1:2
    println(i)
end
x = [1, 2, 3]
y = (a = 1, b = 2)
)jl"},
    {R"jl(a = 0x1
b = 1.50
c = .5e10
f(::Int)=1
T where T<:Real
)jl",
     R"jl(a = 0x01
b = 1.5
c = 0.5e10
f(::Int) = 1
T where {T <: Real}
)jl"},
    {R"jl(

using  Foo,Bar
export  a,b
x = a ? b : c




let a=1,b=2
a+b
end
)jl",
     R"jl(using Foo, Bar
export a, b
x = a ? b : c


let a = 1, b = 2
    a + b
end
)jl"},
    {R"jl(s = """
  hello
    world
  """
function g()
    """
    doc
    """
end
)jl",
     R"jl(s = """
hello
  world
"""
function g()
    return """
    doc
    """
end
)jl"},
    {R"jl(#! format: off
x  =  1
#! format: on
y  =  2
begin x; end
)jl",
     R"jl(#! format: off
x  =  1
#! format: on
y = 2
begin
    x
end
)jl"},
    {R"jl(try
 f()
catch e
 g()
finally
 h()
end
struct S
x::Int
end
m = f(a,
 b)
)jl",
     R"jl(try
    f()
catch e
    g()
finally
    h()
end
struct S
    x::Int
end
m = f(
    a,
    b
)
)jl"},
    {R"jl(g(x) = map(x) do y
 y
end
z = a:b+1
q = a^ b
r = x->x+1  # comment
function h(a) a end
)jl",
     R"jl(g(x) = map(x) do y
    y
end
z = a:(b + 1)
q = a^b
r = x -> x + 1  # comment
function h(a)
    return a
end
)jl"},
};

}  // namespace

int main(int argc, char **argv) {
    if (argc >= 2 && std::strcmp(argv[1], "--format") == 0) return FormatFiles(argc, argv);

    for (const Case &c : kCases) {
        const juliafmt::Result r = juliafmt::Format(c.src);
        CHECK(r.ok);
        if (r.text != c.want) std::fprintf(stderr, "--- got:\n%s--- want:\n%s", r.text.c_str(), c.want);
        CHECK(r.text == c.want);
        // Idempotence (true of Runic on these; Runic itself is not always idempotent).
        CHECK(juliafmt::Format(r.text).text == r.text);
    }

    // Small things: a trailing newline is added, CRLF becomes LF, runs of
    // blank lines are capped at two.
    CHECK(juliafmt::Format("x").text == "x\n");
    CHECK(juliafmt::Format("x = 1\r\ny = 2\r\n").text == "x = 1\ny = 2\n");
    CHECK(juliafmt::Format("a\n\n\n\n\nb\n").text == "a\n\n\nb\n");
    CHECK(juliafmt::Format("").text == "\n");

    // A parse error refuses, with the input handed back and the line given.
    {
        const std::string bad = "x = 1\nf(\n";
        const juliafmt::Result r = juliafmt::Format(bad);
        CHECK(!r.ok);
        CHECK(r.text == bad);
        CHECK(r.error_line >= 1);
    }
    // Runic's own internal assertion (a `let` binding that is a call):
    // refused like Runic refuses it.
    {
        const juliafmt::Result r = juliafmt::Format("let f(x)\n    a\nend\n");
        CHECK(!r.ok);
    }
    // `function ($x)` -- only Julia 1.12's parser calls it ambiguous.
    CHECK(juliafmt::Format("q = :(function ($x)\n    1\nend)\n").ok);

    std::printf("julia_format_test: %d checks passed\n", g_checks);
    return 0;
}
